using System.Globalization;
using Sharpcraft.Client.Assets;
using Sharpcraft.Client.Render;
using Sharpcraft.Common.World;
using Sharpcraft.Framework.Rendering;

namespace Sharpcraft.Client.Tests.Render;

/// <summary>
/// Static mob-skull head vertices against the 26.3 reference sample generated by
/// <c>ref://mc-26.3-analysis/vectors/SkullVectorProbe.java</c>. Every vertex position and UV is
/// compared strictly; this is the source-equivalence evidence that replaces the legacy inline
/// vertex samples (which carried the old face-UV calibration for vertex 1).
/// </summary>
public sealed class SkullRawReferenceTests
{
    private const float Tolerance = 0.002f;

    private static string SamplePath =>
        Path.Combine(AppContext.BaseDirectory, "Repro", "Data", "skull-raw-vectors.golden.txt");

    public static IEnumerable<object[]> GroundSegments =>
        Enumerable.Range(0, 16).Select(segment => new object[] { segment });

    public static IEnumerable<object[]> WallFacings =>
        new byte[] { 2, 3, 4, 5 }.Select(facing => new object[] { (int)facing });

    [Theory]
    [MemberData(nameof(GroundSegments))]
    public void GroundSkullMatchesReference(int segment)
    {
        AssertGroupMatches("ground_" + segment, wall: false, facingOrRotation: (byte)segment);
    }

    [Theory]
    [MemberData(nameof(WallFacings))]
    public void WallSkullMatchesReference(int facing)
    {
        AssertGroupMatches("wall_" + facing, wall: true, facingOrRotation: (byte)facing);
    }

    /// <summary>Player head (8x8x8 head + 0.25-grow hat overlay) against the jar probe sample.</summary>
    [Theory]
    [InlineData("player_ground_0", false, (byte)0)]
    [InlineData("player_wall_2", true, (byte)2)]
    public void PlayerHeadMatchesReference(string tag, bool wall, byte facingOrRotation)
    {
        AssertGroupMatches(tag, wall, facingOrRotation, SkullType.Player, 48);
    }

    [Fact]
    public void EveryGroupInTheSampleIsAccountedFor()
    {
        var groups = new HashSet<string>(StringComparer.Ordinal);
        foreach (var line in File.ReadLines(SamplePath))
        {
            if (line.StartsWith('#') || line.Length == 0)
            {
                continue;
            }

            groups.Add(line.Split('|')[0]);
        }

        Assert.Equal(22, groups.Count); // 16 ground + 4 wall + 2 player
    }

    private static void AssertGroupMatches(string tag, bool wall, byte facingOrRotation,
        SkullType skullType = SkullType.Skeleton, int expectedVertexCount = 24)
    {
        var expected = ReferenceVertices(tag);
        Assert.Equal(expectedVertexCount, expected.Count);

        var atlas = ItemAtlas.FromTextures(new Dictionary<string, TextureData>(StringComparer.Ordinal)
        {
            [SkullModelDefinition.SkeletonTexture] = new(64, 32, new byte[64 * 32 * 4]),
            [SkullModelDefinition.DefaultPlayerSkinTexture] = new(64, 64, new byte[64 * 64 * 4])
        });
        var geometry = new SkullRenderer().Build(
            [new BlockEntityRenderState(0f, 0f, 0f, VanillaBlockEntityTypes.Skull,
                SkullType: skullType, SkullWall: wall,
                SkullFacing: wall ? facingOrRotation : (byte)0,
                SkullRotation: wall ? (byte)0 : facingOrRotation)],
            atlas);
        Assert.Equal(expectedVertexCount, geometry.VertexFloats / ChunkMesher.FloatsPerVertex);

        for (var i = 0; i < expected.Count; i++)
        {
            var e = expected[i];
            var p = VertexFieldReader.Position(geometry.Vertices, i);
            var uv = VertexFieldReader.Uv(geometry.Vertices, i);
            Assert.True(
                MathF.Abs(e.X - p.X) <= Tolerance && MathF.Abs(e.Y - p.Y) <= Tolerance
                    && MathF.Abs(e.Z - p.Z) <= Tolerance
                    && MathF.Abs(e.U - uv.U) <= Tolerance && MathF.Abs(e.V - uv.V) <= Tolerance,
                $"{tag} vertex {i}: ours ({p.X:F4},{p.Y:F4},{p.Z:F4}) uv ({uv.U:F4},{uv.V:F4})"
                    + $" but sample says ({e.X:F4},{e.Y:F4},{e.Z:F4}) uv ({e.U:F4},{e.V:F4})");
        }
    }

    private static List<(float X, float Y, float Z, float U, float V)> ReferenceVertices(string tag)
    {
        var result = new List<(float, float, float, float, float)>();
        foreach (var line in File.ReadLines(SamplePath))
        {
            if (line.StartsWith('#') || line.Length == 0)
            {
                continue;
            }

            var parts = line.Split('|');
            if (parts[0] == tag)
            {
                result.Add((Parse(parts[2]), Parse(parts[3]), Parse(parts[4]), Parse(parts[5]), Parse(parts[6])));
            }
        }

        return result;
    }

    private static float Parse(string value) => float.Parse(value, CultureInfo.InvariantCulture);
}
